async function camera(){if(state.busy||state.demo)return;state.busy=true;$('cameraError').hidden=true;stopCamera();const token=state.token;try{if(!window.isSecureContext)throw Error('Камер HTTPS шаарддаг. Live холбоосыг Safari/Chrome-ийн тусдаа цонхонд нээнэ үү.');if(!navigator.mediaDevices)throw Error('Камер ашиглахын тулд HTTPS хаягаар Safari-д нээнэ үү.');let stream;try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:state.facing},width:{ideal:1280},height:{ideal:720}},audio:false})}catch(e){if(!['OverconstrainedError','NotFoundError'].includes(e.name))throw e;stream=await navigator.mediaDevices.getUserMedia({video:true,audio:false})}if(token!==state.token||document.hidden){stream.getTracks().forEach(t=>t.stop());return}state.camera=stream;$('video').srcObject=stream;await $('video').play();$('placeholder').hidden=true;$('video').parentElement.classList.add('active');const s=stream.getVideoTracks()[0].getSettings();$('cameraStatus').textContent=(s.facingMode==='user'?'УРД КАМЕР':s.facingMode==='environment'?'АРЫН КАМЕР':'КАМЕР')+' · '+(s.width||'?')+' × '+(s.height||'?');$('switch').disabled=$('photo').disabled=$('cameraOff').disabled=false;stream.getVideoTracks()[0].addEventListener('ended',()=>{if(state.camera===stream)stopCamera()});}catch(e){stopCamera();$('cameraError').textContent=error(e)+' Camera зөвшөөрлөө шалгаад Камер асаах товчийг дахин дарна уу.';$('cameraError').hidden=false;toast(error(e))}finally{state.busy=false}}
