const dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB){reject(Error('Хадгалалт дэмжигдээгүй'));return}const req=indexedDB.open('ghost-lens-live-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('sessions',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});dbPromise.catch(()=>{});
