async function startSession(){if(state.session){await endSession();return}try{await dbPromise;const started=performance.now();state.session={id:Date.now(),name:$('sessionName').value.trim()||'Туршилт',utc:new Date().toISOString(),started,mode:state.demo?'demo':'live',events:[]};state.rows=[];state.chunks=[];state.audioBlob=null;if($('recordAudio').checked&&!state.demo){if(!state.mic)toast('Микрофон унтраалттай: зөвхөн хэмжилт бүртгэнэ.');else if(!window.MediaRecorder)toast('Дуу бичлэг дэмжигдээгүй: зөвхөн хэмжилт бүртгэнэ.');else{try{const rec=new MediaRecorder(state.mic);state.recorder=rec;state.recordStop=new Promise(resolve=>{rec.onstop=()=>{state.audioBlob=new Blob(state.chunks,{type:rec.mimeType});resolve()}});rec.ondataavailable=e=>{if(e.data.size)state.chunks.push(e.data)};rec.onerror=()=>toast('Дуу бичихэд алдаа гарлаа.');rec.start(1000)}catch(e){toast('Дуу бичлэг эхэлсэнгүй: '+error(e))}}}$('session').textContent='■ Дуусгаж хадгалах';$('demo').disabled=true;$('recordAudio').disabled=true;addFlag('Бүртгэл эхэлсэн');}catch(e){state.session=null;toast('Хадгалалт боломжгүй: '+error(e))}}
async function endSession(){if(!state.session||state.saving)return;state.saving=true;$('session').disabled=true;addFlag('Бүртгэл дууссан');const session=state.session;state.session=null;if(state.recorder?.state==='recording'){state.recorder.stop();await state.recordStop}state.recorder=null;const record={...session,duration:(performance.now()-session.started)/1000,rows:[...state.rows],audioBlob:state.audioBlob};try{await dbAction('readwrite',s=>s.put(record));toast('Бүртгэл энэ төхөөрөмжид хадгалагдлаа.');await history()}catch(e){download(new Blob([csv(record.rows)],{type:'text/csv;charset=utf-8'}),'ghost-lens-recovery.csv');toast('Хадгалалт бүтэлгүйтлээ. CSV татаж авна уу.')}finally{state.saving=false;$('session').disabled=false;$('session').textContent='Бүртгэл эхлүүлэх';$('demo').disabled=false;$('recordAudio').disabled=false}}
async function history(){try{const records=await dbAction('readonly',s=>s.getAll());urls.forEach(u=>URL.revokeObjectURL(u));urls=[];const h=$('history');h.replaceChildren();if(!records.length){h.textContent='Бүртгэл хараахан алга.';return}for(const r of records.sort((a,b)=>b.id-a.id)){const div=document.createElement('div');div.className='saved';const title=document.createElement('h3');title.textContent=r.name;const meta=document.createElement('small');meta.textContent=new Date(r.utc).toLocaleString()+' · '+Math.round(r.duration)+' сек · '+(r.mode==='demo'?'ДЕМО':'LIVE');div.append(title,meta);for(const [label,fn] of [['CSV',()=>download(new Blob([csv(r.rows)],{type:'text/csv;charset=utf-8'}),`ghost-lens-${r.id}.csv`)],['JSON',()=>{const {audioBlob,...data}=r;download(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),`ghost-lens-${r.id}.json`)}],['Устгах',async()=>{if(confirm('Энэ бүртгэлийг устгах уу?')){await dbAction('readwrite',s=>s.delete(r.id));history()}}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;div.append(b)}if(r.audioBlob?.size){const audio=document.createElement('audio');audio.controls=true;const u=URL.createObjectURL(r.audioBlob);urls.push(u);audio.src=u;div.append(audio);const b=document.createElement('button');b.textContent='Дуу татах';b.onclick=()=>download(r.audioBlob,`ghost-lens-${r.id}.${r.audioBlob.type.includes('mp4')?'m4a':r.audioBlob.type.includes('ogg')?'ogg':'webm'}`);div.append(b)}h.append(div)}}catch(e){$('history').textContent='Браузерын хадгалалт боломжгүй.'}}
function draw(){const c=$('graph'),rect=c.getBoundingClientRect(),ratio=Math.min(devicePixelRatio||1,2),w=Math.max(rect.width,100),h=170;if(c.width!==Math.round(w*ratio)){c.width=Math.round(w*ratio);c.height=h*ratio}const g=c.getContext('2d');g.setTransform(ratio,0,0,ratio,0,0);g.clearRect(0,0,w,h);g.strokeStyle='#26363f';g.lineWidth=1;for(let i=0;i<5;i++){g.beginPath();g.moveTo(0,i*h/4);g.lineTo(w,i*h/4);g.stroke()}const now=performance.now();for(const [key,color,normalize]of [['audio','#69f6d4',v=>(v+96)/96],['motion','#b29aff',v=>v/5],['mag','#f5c76e',v=>v/150]]){g.strokeStyle=color;g.lineWidth=2;g.beginPath();let connected=false;for(const r of graphRows){if(r[key]==null){connected=false;continue}const x=w*(1-(now-r.t)/60000),y=h*(1-clamp(normalize(r[key]),0,1));if(connected)g.lineTo(x,y);else g.moveTo(x,y);connected=true}g.stroke()}g.strokeStyle='#ffbf72';g.lineWidth=1;for(const e of state.events){if(now-e.t>60000)continue;const x=w*(1-(now-e.t)/60000);g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}}
function tick(){const now=performance.now();let audio=null,motion=null,mag=null;if(state.demo){audio=-56+15*Math.sin(now/1600)+(Math.sin(now/3200)>.93?25:0);motion=Math.abs(Math.sin(now/2100))*.45+(Math.sin(now/4000)>.96?1.8:0);mag=null}else{if(state.analyser){const data=new Float32Array(state.analyser.fftSize);state.analyser.getFloatTimeDomainData(data);audio=dbfs(data)}if(now-state.motionAt<1500)motion=state.motion;if(magnetic.vector&&now-magnetic.at<1500)mag=Math.hypot(...magnetic.vector)}state.audio=audio;for(const [key,value,bar,scale]of [['audio',audio,'audioBar',v=>(v+96)/96],['motion',motion,'motionBar',v=>v/5],['mag',mag,'magBar',v=>v/100]]){$(key+'Value').textContent=value==null?'—':value.toFixed(1);$(bar).style.width=value==null?'0%':clamp(scale(value)*100,0,100)+'%'}const row={t:now,utc:new Date().toISOString(),elapsed:state.session?(now-state.session.started)/1000:null,mode:state.demo?'demo':'live',audio,motion,mag,magX:state.demo||mag==null?null:magnetic.vector?.[0],magY:state.demo||mag==null?null:magnetic.vector?.[1],magZ:state.demo||mag==null?null:magnetic.vector?.[2],magBaseline:state.demo?null:magnetic.baseline.value,magSigma:state.demo?null:magnetic.baseline.sigma,magHz:!state.demo&&mag!=null?observedMagneticHz(magnetic.stamps):null,magDelta:!state.demo&&mag!=null&&magnetic.baseline.value!=null?Math.abs(mag-magnetic.baseline.value):null,magSource:state.demo?'simulation':mag!=null?'device_magnetometer':'unavailable'};graphRows.push(row);graphRows=graphRows.filter(r=>now-r.t<=60000);if(state.session){state.rows.push(row);if(row.magDelta!=null&&magnetic.baseline.check(mag,Number($('magThreshold').value)))addFlag('Соронзон орны өөрчлөлт |ΔB| '+row.magDelta.toFixed(1)+' µT',true);const elapsed=Math.floor(row.elapsed);$('clock').textContent=String(Math.floor(elapsed/60)).padStart(2,'0')+':'+String(elapsed%60).padStart(2,'0');if(audio>-25||motion>1.5)addFlag(audio>-25?'Дууны түвшин өссөн':'Утасны хөдөлгөөн нэмэгдсэн',true);if(row.elapsed>=1800){toast('30 минутын бүртгэл дууслаа.');endSession()}}else $('clock').textContent='00:00';draw()}
$('camera').onclick=camera;$('cameraOff').onclick=stopCamera;$('switch').onclick=()=>{state.facing=state.facing==='environment'?'user':'environment';camera()};$('mic').onclick=mic;$('motion').onclick=motion;$('session').onclick=startSession;$('flag').onclick=()=>{addFlag($('note').value.trim()||'Гараар тэмдэглэсэн');$('note').value=''};$('refresh').onclick=history;
$('photo').onclick=()=>{const v=$('video');if(!v.videoWidth)return;const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(b=>{if(b)download(b,'ghost-lens-'+Date.now()+'.jpg')},'image/jpeg',.92);addFlag('Камерын зураг авсан')};
