// Actual magnetic measurements, with no synthetic fallback in live mode.
const magnetic={sensor:null,vector:null,at:0,stamps:[],baseline:new MagneticBaseline()};
function stopMagnetic(){magnetic.sensor?.stop();magnetic.sensor=null;magnetic.vector=null;magnetic.at=0;magnetic.stamps=[];magnetic.baseline=new MagneticBaseline();$('calibrate').disabled=true;$('magStart').textContent='Мэдрэгч холбох';$('magStatus').textContent='Мэдрэгч холбогдоогүй'}
function magneticMessage(message){$('magStatus').textContent=message;$('calibrationStatus').textContent=message}
$('magStart').onclick=()=>{if(state.demo)return toast('Бодит горимд буцаж мэдрэгчээ холбоно уу.');if(magnetic.sensor){stopMagnetic();return}if(!('Magnetometer' in window)){magneticMessage('Энэ браузер magnetometer уншихгүй. iPhone app эсвэл гадаад хэмжигч хэрэгтэй.');return}try{const sensor=new Magnetometer({frequency:20});magnetic.sensor=sensor;sensor.addEventListener('reading',()=>{if(magnetic.sensor!==sensor)return;if(![sensor.x,sensor.y,sensor.z].every(Number.isFinite))return;magnetic.vector=[sensor.x,sensor.y,sensor.z];magnetic.at=performance.now();magnetic.stamps.push(magnetic.at);magnetic.stamps=magnetic.stamps.filter(t=>magnetic.at-t<=2000);$('magStatus').textContent='LIVE · Төхөөрөмжийн magnetometer';$('calibrate').disabled=false;$('magStart').textContent='Мэдрэгч салгах';const value=Math.hypot(...magnetic.vector);if(magnetic.baseline.add(value,magnetic.at))$('calibrationStatus').textContent='Суурь хэмжилт бэлэн · '+magnetic.baseline.value.toFixed(1)+' µT'});sensor.addEventListener('error',event=>{stopMagnetic();magneticMessage('Мэдрэгч ажилласангүй: '+error(event.error||event))});sensor.start()}catch(e){stopMagnetic();magneticMessage(error(e))}};
$('calibrate').onclick=()=>{if(!magnetic.vector)return;magnetic.baseline.start(performance.now());$('calibrationStatus').textContent='3 секунд нэг байрлалд хөдөлгөөнгүй барина уу…'};
$('magThreshold').oninput=()=>{$('magThresholdValue').textContent=$('magThreshold').value+' µT'};
setInterval(()=>{const valid=!state.demo&&magnetic.vector&&performance.now()-magnetic.at<1500;for(const [id,i]of [['magX',0],['magY',1],['magZ',2]])$(id).textContent=valid?magnetic.vector[i].toFixed(1)+' µT':'—';$('magBase').textContent=valid&&magnetic.baseline.value!=null?magnetic.baseline.value.toFixed(1)+' µT':'—';$('magSigma').textContent=valid&&magnetic.baseline.sigma!=null?magnetic.baseline.sigma.toFixed(2)+' µT':'—';const hz=observedMagneticHz(magnetic.stamps);$('magHz').textContent=valid&&hz!=null?hz.toFixed(1)+' Hz':'—';$('magDelta').textContent=valid&&magnetic.baseline.value!=null?Math.abs(Math.hypot(...magnetic.vector)-magnetic.baseline.value).toFixed(1)+' µT':'—';$('magStart').disabled=state.demo;$('calibrate').disabled=!valid;if(magnetic.sensor&&!valid&&!state.demo)$('magStatus').textContent='Мэдрэгчийн шинэ өгөгдөл хүлээж байна…'},200);
// Display observed audio events and explicitly enabled browser speech recognition.
let soundDetector=new SoundEvents(),wasAnalysing=false;const soundEntries=[];
let utteranceSerial=0,activeQuestion=null;
function soundEntry(title,detail,source,score=null){const entry={id:'utterance-'+Date.now()+'-'+(++utteranceSerial),sequence:utteranceSerial,utc:new Date().toISOString(),title,detail,source,score,role:'unmarked'};soundEntries.unshift(entry);soundEntries.length=Math.min(soundEntries.length,80);if(state.session){(state.session.soundEvents??=[]).push({...entry});addFlag(((source==='speech'||source==='local')?'Яриа → текст: ':'Дуу: ')+title+' · '+detail)}renderSoundHistory();return entry}
function annotateSpeech(entry,kind){if(state.demo||!['speech','local'].includes(entry.source))return;if(kind==='reply'&&(!activeQuestion||entry.sequence<=activeQuestion.sequence||entry.id===activeQuestion.id)){toast('Эхлээд өмнөх яриаг асуулт гэж тэмдэглэнэ үү.');return}entry.role=kind;entry.markedUtc=new Date().toISOString();if(kind==='question'){delete entry.questionId;delete entry.questionText;activeQuestion={id:entry.id,sequence:entry.sequence,title:entry.title,utc:entry.utc}}else{entry.questionId=activeQuestion.id;entry.questionText=activeQuestion.title}if(state.session){const events=state.session.soundEvents??=[];const index=events.findIndex(e=>e.id===entry.id);if(index<0)events.push({...entry});else events[index]={...entry};(state.session.interactions??=[]).push({...entry,annotationSource:'user',meaningConfirmed:false});addFlag((kind==='question'?'Миний хэлсэн үг / асуулт: ':'Хэрэглэгч хариу гэж тэмдэглэсэн: ')+entry.title+(kind==='reply'?' · Асуулт: '+entry.questionText:''))}renderSoundHistory()}
function renderSoundHistory(){const list=$('soundHistory');list.replaceChildren();for(const e of soundEntries.slice(0,12)){const li=document.createElement('li'),label=document.createElement('strong'),small=document.createElement('small'),p=document.createElement('p');label.textContent=e.title;small.textContent=new Date(e.utc).toLocaleTimeString()+' · '+(e.source==='speech'?'Яриа таних үйлчилгээ':e.source==='local'?'Whisper · төхөөрөмж дээр':'Сигналын дүрмийн тайлбар');p.textContent=e.detail;li.append(label,small,p);if(e.role!=='unmarked'){const mark=document.createElement('p');mark.className='speech-mark';mark.textContent=e.role==='question'?'◎ Миний хэлсэн үг / асуулт · хэрэглэгч тэмдэглэсэн':'↳ Хариу гэж тэмдэглэсэн · «'+e.questionText+'» · эх үүсвэр/утга баталгаагүй';li.append(mark)}if(['speech','local'].includes(e.source)){const controls=document.createElement('div');controls.className='utterance-actions';for(const [kind,text]of [['question','Миний хэлсэн үг / асуулт'],['reply','Хариу гэж тэмдэглэх']]){const button=document.createElement('button');button.textContent=text;button.disabled=state.demo||(kind==='reply'&&(!activeQuestion||e.sequence<=activeQuestion.sequence));button.onclick=()=>annotateSpeech(e,kind);controls.append(button)}li.append(controls)}list.append(li)}$('questionStatus').textContent=activeQuestion?'Тэмдэглэсэн асуулт: «'+activeQuestion.title+'»':'Асуулт тэмдэглээгүй.';$('clearQuestion').disabled=!activeQuestion}
$('clearQuestion').onclick=()=>{activeQuestion=null;renderSoundHistory()};
const speech={recognizer:null,active:false};
function stopSpeech(){speech.active=false;const rec=speech.recognizer;speech.recognizer=null;if(rec){rec.onresult=null;rec.onend=null;rec.onerror=null;try{rec.abort()}catch{}}$('speechToggle').textContent='Яриа → текст асаах';$('speechLang').disabled=false;$('speechInterim').textContent='';$('speechStatus').textContent='Яриа таних унтраалттай.'}
$('speechToggle').onclick=()=>{if(speech.active){stopSpeech();return}if(state.demo){toast('Яриа танихын тулд бодит горимд буцна уу.');return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){$('speechStatus').textContent='Энэ браузер яриа таних API дэмжихгүй. Тусдаа Chrome/Edge/Safari цонхонд туршина уу.';return}try{const rec=new Recognition();speech.recognizer=rec;speech.active=true;rec.lang=$('speechLang').value;rec.continuous=true;rec.interimResults=true;rec.maxAlternatives=1;$('speechLang').disabled=true;$('speechToggle').textContent='■ Яриа таних зогсоох';$('speechStatus').textContent='Холбогдож байна…';rec.onstart=()=>{if(speech.recognizer===rec)$('speechStatus').textContent='СОНСОЖ БАЙНА · Браузерын яриа таних үйлчилгээ'};rec.onresult=event=>{if(speech.recognizer!==rec)return;let interim='';for(let i=event.resultIndex;i<event.results.length;i++){const result=event.results[i],alt=result[0];const text=alt.transcript.trim();if(!text)continue;if(result.isFinal){const score=Number.isFinite(alt.confidence)&&alt.confidence>0?alt.confidence:null;const detail='Танигдсан текст · Алдаатай байж болно.'+(score!=null?' Браузерын оноо: '+Math.round(score*100)+'%.':' Итгэлцлийн оноо өгөгдөөгүй.');soundEntry(text,detail,'speech',score);$('soundTitle').textContent=text;$('soundMeaning').textContent='Хүний ярианаас танигдсан текст';$('soundEvidence').textContent=detail}else interim+=text+' '}$('speechInterim').textContent=interim?'Түр танилт: '+interim:''};rec.onerror=event=>{if(speech.recognizer!==rec)return;stopSpeech();$('speechStatus').textContent=({'not-allowed':'Микрофон/яриа таних зөвшөөрөл өгөөгүй.','service-not-allowed':'Браузерын яриа таних үйлчилгээ зөвшөөрөгдөөгүй.','network':'Яриа таних сүлжээний алдаа. Интернет болон браузерын үйлчилгээг шалга.','language-not-supported':'Сонгосон хэл дэмжигдэхгүй. Өөр хэл сонгох эсвэл өөр таних үйлчилгээ шаардлагатай.','no-speech':'Яриа танигдсангүй. Чимээгүй орчинд дахин асааж туршаарай.','audio-capture':'Микрофоныг уншиж чадсангүй. Бусад app-ийн микрофон ашиглалтыг шалга.'})[event.error]||'Яриа таних алдаа: '+event.error};rec.onend=()=>{if(speech.recognizer!==rec)return;stopSpeech();$('speechStatus').textContent='Яриа таних дууссан. Дахин асаах товчийг дарна уу.'};rec.start()}catch(e){stopSpeech();$('speechStatus').textContent=error(e)}};
setInterval(()=>{const active=!!state.analyser&&!state.demo;$('speechToggle').disabled=state.demo;$('soundStatus').textContent=state.demo?'ДЕМО · БОДИТ ДУУ ТАНИХГҮЙ':active?'LIVE · СИГНАЛЫН ТАЙЛБАР':'МИКРОФОН УНТРААЛТТАЙ';if(!active){if(wasAnalysing)soundDetector=new SoundEvents();wasAnalysing=false;return}wasAnalysing=true;const data=new Float32Array(state.analyser.fftSize),spectrum=new Float32Array(state.analyser.frequencyBinCount);state.analyser.getFloatTimeDomainData(data);state.analyser.getFloatFrequencyData(spectrum);const e=soundDetector.update(dbfs(data),performance.now(),concentratedSpectrum(spectrum));if(!e)return;$('soundTitle').textContent=e.title;$('soundMeaning').textContent=e.possible;$('soundEvidence').textContent=`${Math.round(e.duration)} мс · оргил ${e.peak.toFixed(1)} dBFS · Ангилалт баталгаагүй, дүрэмд суурилсан`;soundEntry(e.title,e.possible+' '+Math.round(e.duration)+' мс, '+e.peak.toFixed(1)+' dBFS','signal')},50);
// Opt-in local multilingual transcription. No microphone samples sent to an API.
const local={worker:null,ready:false,phase:'idle',stream:null,recorder:null,timer:null,recordTimer:null,token:0,id:0,cancelled:false,chunks:[],started:0,clip:null,clipUrl:null};
function localButtons(){const active=local.phase!=='idle';$('localLoad').disabled=active||local.ready||state.demo;$('localRecord').disabled=state.demo||(!local.ready&&local.phase!=='recording')||(active&&local.phase!=='recording');$('localRecord').textContent=local.phase==='recording'?'■ Зогсоож текст болгох':'● 15 секунд ярих';$('localCancel').disabled=!active;$('speechToggle').disabled=active||state.demo}
function cancelLocal(){if(local.phase==='idle')return;local.cancelled=true;local.token++;clearTimeout(local.timer);clearInterval(local.recordTimer);local.stream?.getTracks().forEach(t=>t.stop());local.stream=null;if(local.recorder?.state==='recording'){local.recorder.onstop=null;try{local.recorder.stop()}catch{}}local.recorder=null;if(['loading','processing'].includes(local.phase)){local.worker?.terminate();local.worker=null;local.ready=false}local.phase='idle';local.chunks=[];$('localStatus').textContent='Цуцлагдсан. Бичлэг зогссон.';localButtons()}
function localWorker(){const worker=new Worker('whisper-worker.mjs',{type:'module'});local.worker=worker;worker.onmessage=event=>{if(local.worker!==worker)return;const data=event.data;if(data.type==='progress'){$('localStatus').textContent='Загвар татаж байна… '+(data.file||'')+(Number.isFinite(data.progress)?' '+Math.round(data.progress)+'%':'')}else if(data.type==='ready'){local.ready=true;local.phase='idle';$('localLoad').textContent='✓ Загвар бэлэн';$('localStatus').textContent='Загвар бэлэн. 15 секунд ярих товчийг дарна уу.';localButtons()}else if(data.type==='result'&&data.id===local.id){local.phase='idle';const text=data.text.trim();if(text){soundEntry(text,'Автомат олон хэл · Whisper tiny. Алдаатай, зохиомол танилт байж болох тул бичлэгтэй тулгаж шалгана.','local');$('soundTitle').textContent=text;$('soundMeaning').textContent='Laptop дээр танигдсан текст · Эх хэлээр';$('soundEvidence').textContent='Автомат олон хэл. Хэлний нэр/итгэлцлийн оноог энэ горим тусад нь буцаахгүй.';$('localStatus').textContent='Текст гарлаа. Дахин 15 секундээр үргэлжлүүлж болно.'}else $('localStatus').textContent='Текст танигдсангүй. Илүү тод, урт өгүүлбэрээр дахин туршина уу.';local.chunks=[];localButtons()}else if(data.type==='error'){local.phase='idle';local.stream?.getTracks().forEach(t=>t.stop());local.stream=null;if(!local.ready){worker.terminate();local.worker=null}$('localStatus').textContent='Олон хэлний загвар ажилласангүй: '+data.message+' Интернет, загвар таталт эсвэл браузерын санах ойг шалга.';localButtons()}};worker.onerror=e=>{if(local.worker!==worker)return;worker.terminate();local.worker=null;local.ready=false;local.phase='idle';$('localStatus').textContent='Загварын Worker ачаалсангүй. Интернет, CDN болон браузерын тохиргоог шалга.';localButtons()};return worker}
$('localLoad').onclick=()=>{if(state.demo||local.phase!=='idle')return;local.cancelled=false;local.phase='loading';$('localStatus').textContent='Олон хэлний загвар ачаалж байна… эхний удаа хугацаа шаардана.';localButtons();try{(local.worker||localWorker()).postMessage({type:'load'})}catch(e){local.phase='idle';$('localStatus').textContent=error(e);localButtons()}};
async function resampleLocal(blob){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('AudioContext дэмжихгүй');const context=new C();try{const decoded=await context.decodeAudioData(await blob.arrayBuffer());const length=Math.min(Math.ceil(decoded.duration*16000),16*16000);if(!length)throw Error('Бичлэг хоосон');const offline=new OfflineAudioContext(1,length,16000),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();const rendered=await offline.startRendering();return new Float32Array(rendered.getChannelData(0))}finally{await context.close()}}
async function finishLocal(){if(local.phase!=='recording')return;clearTimeout(local.timer);clearInterval(local.recordTimer);local.phase='processing';$('localStatus').textContent='Бичлэгийг laptop дээр боловсруулж байна…';localButtons();try{local.recorder.stop()}catch(e){cancelLocal();$('localStatus').textContent=error(e)}}
$('localRecord').onclick=async()=>{if(local.phase==='recording'){finishLocal();return}if(local.phase!=='idle'||!local.ready||state.demo)return;stopSpeech();local.cancelled=false;local.phase='permission';const token=++local.token;localButtons();$('localStatus').textContent='Микрофоны зөвшөөрөл хүлээж байна…';try{if(!window.MediaRecorder)throw Error('Энэ браузер MediaRecorder дэмжихгүй');const stream=state.mic?new MediaStream(state.mic.getAudioTracks().map(t=>t.clone())):await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(token!==local.token||document.hidden){stream.getTracks().forEach(t=>t.stop());return}local.stream=stream;local.chunks=[];const recorder=new MediaRecorder(stream);local.recorder=recorder;recorder.ondataavailable=e=>{if(e.data.size)local.chunks.push(e.data)};recorder.onstop=async()=>{const blob=new Blob(local.chunks,{type:recorder.mimeType});stream.getTracks().forEach(t=>t.stop());local.stream=null;if(token!==local.token||local.cancelled)return;try{showLocalClip(blob);const audio=await resampleLocal(blob);if(token!==local.token)return;if(dbfs(audio)<-50){local.phase='idle';$('localStatus').textContent='Дуу хэт сул/чимээгүй. Текст зохиохоос сэргийлж танилтыг алгаслаа.';localButtons();return}const id=++local.id;local.worker.postMessage({type:'transcribe',id,audio},[audio.buffer])}catch(e){local.phase='idle';$('localStatus').textContent=error(e);localButtons()}};recorder.onerror=()=>{cancelLocal();$('localStatus').textContent='Дуу бичлэгт алдаа гарлаа.'};recorder.start(500);local.phase='recording';local.started=performance.now();localButtons();$('localStatus').textContent='Сонсож байна · 15 сек · Та хүссэн хэлээрээ ярьж болно.';local.recordTimer=setInterval(()=>{$('localStatus').textContent='Сонсож байна · '+Math.max(0,15-Math.floor((performance.now()-local.started)/1000))+' сек үлдлээ'},500);local.timer=setTimeout(finishLocal,15000)}catch(e){if(token!==local.token)return;local.stream?.getTracks().forEach(t=>t.stop());local.stream=null;local.phase='idle';$('localStatus').textContent=error(e);localButtons()}};
$('localCancel').onclick=cancelLocal;setInterval(localButtons,300);

function showLocalClip(blob){if(local.clipUrl)URL.revokeObjectURL(local.clipUrl);local.clip=blob;local.clipUrl=URL.createObjectURL(blob);$('localPlayback').src=local.clipUrl;$('localClip').hidden=false;}
$('localDownload').onclick=()=>{if(local.clip)download(local.clip,'ghost-lens-speech-'+Date.now()+'.'+(local.clip.type.includes('mp4')?'m4a':local.clip.type.includes('ogg')?'ogg':'webm'))};
